create table if not exists public.erp_regras_decimais(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,codigo text not null,descricao text not null,casas integer not null check(casas between 0 and 8),ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),unique(empresa_id,codigo));
alter table public.erp_regras_decimais enable row level security;
drop policy if exists erp_regras_decimais_all on public.erp_regras_decimais;
create policy erp_regras_decimais_all on public.erp_regras_decimais for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
grant select,insert,update,delete on public.erp_regras_decimais to authenticated;
create or replace function public.erp_decimal_salvar_regra(p_codigo text,p_descricao text,p_casas integer) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_empresa uuid:=public.erp_current_empresa_id();v_id uuid; begin if v_empresa is null and not public.erp_is_master() then raise exception 'Empresa não identificada.'; end if; if btrim(coalesce(p_codigo,''))='' or btrim(coalesce(p_descricao,''))='' then raise exception 'Código e descrição são obrigatórios.'; end if; if p_casas<0 or p_casas>8 then raise exception 'Quantidade de casas inválida.'; end if; insert into public.erp_regras_decimais(empresa_id,codigo,descricao,casas) values(v_empresa,upper(btrim(p_codigo)),btrim(p_descricao),p_casas) on conflict(empresa_id,codigo) do update set descricao=excluded.descricao,casas=excluded.casas,ativo=true,atualizado_em=now() returning id into v_id; return v_id; end $$;
revoke all on function public.erp_decimal_salvar_regra(text,text,integer) from public,anon;
grant execute on function public.erp_decimal_salvar_regra(text,text,integer) to authenticated;